class Solution { public String reformat(String s){ StringBuilder d=new StringBuilder(), l=new StringBuilder(); for(int i=0;i<s.length();i++){ char c=s.charAt(i); if(c>=48&&c<=57) d.append(c); else l.append(c); } if(Math.abs(d.length()-l.length())>1) return ""; StringBuilder r=new StringBuilder(); boolean dl=d.length()>=l.length(); for(int i=0;i<s.length();i++){ if(dl){ if(i<d.length()) r.append(d.charAt(i)); if(i<l.length()) r.append(l.charAt(i)); } else { if(i<l.length()) r.append(l.charAt(i)); if(i<d.length()) r.append(d.charAt(i)); } } return r.toString(); } }